import{_ as a,o as e,c as i,a8 as t}from"./chunks/framework.DpsX1MbM.js";const k=JSON.parse('{"title":"DFlash2","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/DFlash2.md","filePath":"sections/concepts/DFlash2.md","lastUpdated":1788846900000}'),n={name:"concepts/DFlash2.md"};function h(l,s,r,o,p,d){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="dflash2" tabindex="-1">DFlash2 <a class="header-anchor" href="#dflash2" aria-label="Permalink to &quot;DFlash2&quot;">​</a></h1><p>DFlash2 extends the one-pass DFlash draft with grouped dynamic convolutions and a low-rank selector that chooses a coherent path through the target head&#39;s top-k candidates. In SpecForge it is a <strong>draft architecture</strong>, not a separate training strategy or feature protocol.</p><table tabindex="0"><thead><tr><th>Boundary</th><th>DFlash2 value</th></tr></thead><tbody><tr><td>Training strategy</td><td><code>training.strategy: dflash</code></td></tr><tr><td>Draft architecture</td><td><code>DFlash2DraftModel</code></td></tr><tr><td>Online server capture</td><td><code>--spec-capture-method dflash</code></td></tr><tr><td>Offline feature schema</td><td>DFlash <code>input_ids</code>, <code>loss_mask</code>, <code>hidden_states</code></td></tr><tr><td>Export target</td><td><code>specforge export --to hf</code></td></tr><tr><td>SGLang serving algorithm</td><td><code>DFLASH</code></td></tr></tbody></table><p>This reuse is intentional. The convolution and selector run entirely in the draft, so the target server captures the same layers and the trainer consumes the same tensors as standard DFlash.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><p>Every attention and MLP sublayer is wrapped by a grouped, dynamic depthwise convolution. <code>conv_kernel_size</code> controls its number of causal taps and <code>conv_group_size</code> controls how channels share dynamic kernel coefficients. The base kernel is an identity and the kernel projection is zero-initialized, so a new convolution starts as an exact no-op.</p><p>The candidate selector first takes the target LM head&#39;s unary top-k at every proposal position. It then adds a low-rank transition score conditioned on the draft hidden state and the predecessor token. The successor codebook is zero-initialized, so a new selector initially preserves unary DFlash scores.</p><p>A DFlash2 draft config must explicitly select the architecture and provide its four additional model fields:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;architectures&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DFlash2DraftModel&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;dflash_config&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;block_size&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;target_layer_ids&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">31</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">46</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">61</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;mask_token_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">248070</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;conv_kernel_size&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;conv_group_size&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;selector_rank&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;selector_top_k&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>conv_kernel_size</code> must be positive and no larger than <code>block_size</code>; <code>conv_group_size</code> must divide <code>hidden_size</code>; <code>selector_rank</code> must be positive; and <code>selector_top_k</code> must be between 1 and <code>vocab_size</code>. The checked-in complete configuration is <a href="https://github.com/sgl-project/SpecForge/blob/main/configs/qwen3.6-27b-dflash2.json" target="_blank" rel="noreferrer"><code>configs/qwen3.6-27b-dflash2.json</code></a>. Unlike a standard DFlash draft, DFlash2 cannot be selected through target-derived defaults: provide this config or a pretrained DFlash2 directory whose <code>config.json</code> declares <code>DFlash2DraftModel</code>.</p><h2 id="selector-objective-and-schedule" tabindex="-1">Selector objective and schedule <a class="header-anchor" href="#selector-objective-and-schedule" aria-label="Permalink to &quot;Selector objective and schedule&quot;">​</a></h2><p>The base head keeps the configured DFlash, D-PACE, CE/LK, and TV behavior. The selector has a separate categorical cross-entropy objective over the strict unary top-k candidate set. Tokens whose gold target is outside that set do not contribute selector CE; <code>selector_coverage</code> measures how often it is present.</p><p>Configure its weight and optimizer-step schedule in the training YAML:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">training</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  strategy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">dflash</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  dflash2_selector_loss_alpha</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  dflash2_selector_warmup_ratio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0005</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  dflash2_selector_ramp_ratio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0005</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  dflash2_selector_stop_gradient</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><p>The effective selector weight is zero during warmup, increases linearly during the ramp, and then stays at <code>dflash2_selector_loss_alpha</code>. Warmup and ramp are fractions of the resolved optimizer-step horizon, not micro-batch counts. With a positive configured alpha the selector remains in the optimizer and autograd graph during warmup, which keeps DDP behavior stable. Setting the configured alpha to exactly zero statically disables selector training, freezes its parameters, and excludes them from the optimizer.</p><p><code>dflash2_selector_stop_gradient</code> controls whether the selector CE also trains the parameters it reads. It defaults to <code>false</code>, which keeps the coupled behavior: selector CE flows back into the unary logits and draft hidden states. Setting it to <code>true</code> detaches both inputs inside the selector term, so only the selector&#39;s own parameters receive that gradient while the primary DFlash/D-PACE/LK objective keeps its unchanged gradient path.</p><p>The combined base and selector numerator is normalized with the DFlash valid effective-token denominator. Selector metrics retain their own denominators so coverage, accuracy, probability, and CE remain interpretable when only part of the unary candidate set covers the target.</p><h2 id="train-online-or-offline" tabindex="-1">Train online or offline <a class="header-anchor" href="#train-online-or-offline" aria-label="Permalink to &quot;Train online or offline&quot;">​</a></h2><p>The managed-local Qwen3.6-27B example owns one target capture process and one trainer process. Update its model/data paths and GPU allocation, then run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">specforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> train</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/configs/online/disaggregated/managed-local/qwen3.6-27b-dflash2-disaggregated.yaml</span></span></code></pre></div><p>For external online services, use the same YAML model and training fields but omit <code>deployment.disaggregated.managed_local</code>, provide the Mooncake endpoints and <code>server_urls</code>, and start SGLang with <code>--spec-capture-method dflash</code>. Its auxiliary layer IDs must exactly match <code>dflash_config.target_layer_ids</code>.</p><p>Offline DFlash2 uses the normal DFlash feature preparation path:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">torchrun</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --nproc_per_node=8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  scripts/prepare_hidden_states.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --strategy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dflash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --target-model-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/Qwen3.6-27B</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --draft-model-config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> configs/qwen3.6-27b-dflash2.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/train.jsonl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cache/hidden_states/qwen3.6-27b-dflash2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --chat-template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen3.5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --max-length</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8192</span></span></code></pre></div><p>Point an offline training YAML at that directory with <code>data.hidden_states_path</code>; keep <code>training.strategy: dflash</code> and the same draft config. DFlash2 supports the DFlash <code>eager</code>, <code>sdpa</code>, and <code>flex_attention</code> training backends and the same full/sliding per-layer layouts.</p><h2 id="export-and-serve" tabindex="-1">Export and serve <a class="header-anchor" href="#export-and-serve" aria-label="Permalink to &quot;Export and serve&quot;">​</a></h2><p>Export the runtime checkpoint as a Hugging Face draft directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">specforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --checkpoint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./outputs/qwen3.6-27b-dflash2-disaggregated-with-selector/qwen3.6-27b-dflash2-disaggregated-with-selector-latest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --draft-config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> configs/qwen3.6-27b-dflash2.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./exports/qwen3.6-27b-dflash2</span></span></code></pre></div><p>Use an SGLang release or revision that contains DFlash2 support (<a href="https://github.com/sgl-project/sglang/pull/35371" target="_blank" rel="noreferrer">SGLang PR #35371</a>). The serving algorithm remains <code>DFLASH</code>; <code>DFlash2DraftModel</code> in the exported config selects the convolution and path-selector implementation. Optional <code>dflash_config.output_multiplier</code> and <code>final_logit_softcapping</code> are applied to unary logits in both SpecForge&#39;s local generation path and the matching serving contract.</p><p>Training supports the shared DFlash-family <code>gqa</code>, <code>mha</code>, and <code>mla</code> attention modes. SGLang DFlash-family serving currently supports GQA/MHA layouts, so do not use an MLA DFlash2 export for a serving benchmark until the corresponding loader and kernels are available.</p>`,29)])])}const g=a(n,[["render",h]]);export{k as __pageData,g as default};
